#[derive(Serialize, Deserialize)]
struct Link { rel: String, href: Url, method: String } // carrier survives serde_json

// producer: embed a link, not the resource representation
let payment = Link { rel: "payment".into(),
    href: base.join(&format!("/payments/{pid}"))?, method: "GET".into() };

// consumer: dereference the link, never a hardcoded URL
let resp = client.get(payment.href).send()?.error_for_status()?;
let paid: Payment = resp.json().await?;
